P_Rot := S1 AND T1.ET < T#4s;
P_Gelb := S1 AND ((T1.ET >= T#3s AND T1.ET < T#4s) OR T1.ET >= T#7s);
P_Gruen := S1 AND T1.ET >= T#4s AND T1.ET < T#7s;

VAR
  Schritt : INT;
  T1 : TON;
  Dauer : TIME;
END_VAR

IF NOT S1 THEN
  Schritt := 0;
ELSIF Schritt = 0 THEN
  Schritt := 1;
END_IF;

CASE Schritt OF
  1, 3: Dauer := T#3s;
  2, 4: Dauer := T#1s;
END_CASE;

T1(IN := Schritt > 0 AND NOT T1.Q, PT := Dauer);
IF T1.Q THEN
  Schritt := Schritt + 1;
  IF Schritt > 4 THEN
    Schritt := 1;
  END_IF;
END_IF;

P_Rot := Schritt = 1 OR Schritt = 2;
P_Gelb := Schritt = 2 OR Schritt = 4;
P_Gruen := Schritt = 3;

